module benchmark/solution
// DO NOT CHANGE THE MODULE DECLARATION ABOVE!

import std/string (chars)

pure func pairs() -> [(int, string)] =
  [(1000, "M"), (900, "CM"), (500, "D"), (400, "CD"), (100, "C"), (90, "XC"),
   (50, "L"), (40, "XL"), (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")]

pure func encode(n: int, ps: [(int, string)]) -> string =
  match ps {
    [] => "",
    (v, s) :: rest => if n >= v then "${s}${encode(n - v, ps)}" else encode(n, rest)
  }

export pure func toRoman(n: int) -> string = encode(n, pairs())

pure func charValue(c: string) -> int =
  match c {
    "I" => 1,
    "V" => 5,
    "X" => 10,
    "L" => 50,
    "C" => 100,
    "D" => 500,
    "M" => 1000,
    _ => 0
  }

pure func decode(cs: [string]) -> int =
  match cs {
    [] => 0,
    c :: rest => {
      let v = charValue(c);
      match rest {
        [] => v,
        d :: _ => if v < charValue(d) then decode(rest) - v else v + decode(rest)
      }
    }
  }

export pure func fromRoman(s: string) -> int = decode(chars(s))

export pure func roundtrip(n: int) -> bool = fromRoman(toRoman(n)) == n

export pure func distinctEncoding(a: int, b: int) -> bool =
  a == b || toRoman(a) != toRoman(b)

export func main() -> () ! {IO} {
  println(toRoman(1994));
  println(toRoman(58));
  println(toRoman(3999));
  println(show(fromRoman("MCMXCIV")));
  println(show(fromRoman("LVIII")));
  println(show(roundtrip(2024)));
  println(show(distinctEncoding(4, 6)))
}

